begin;
create extension if not exists pgtap with schema extensions;
select extensions.plan(14);
select ok((select relrowsecurity from pg_class where oid='public.billing_plans'::regclass),'billing plans use RLS');
select ok((select relrowsecurity from pg_class where oid='public.billing_subscriptions'::regclass),'subscriptions use RLS');
select ok((select relrowsecurity from pg_class where oid='public.billing_payments'::regclass),'payments use RLS');
select ok((select relrowsecurity from pg_class where oid='public.billing_webhook_events'::regclass),'webhook events use RLS');
select ok((select relrowsecurity from pg_class where oid='public.billing_documents'::regclass),'billing documents use RLS');
select ok((select relrowsecurity from pg_class where oid='public.billing_reconciliation_jobs'::regclass),'reconciliation jobs use RLS');
select ok(exists(select 1 from pg_indexes where schemaname='public' and indexname='billing_one_pending_payment_per_owner'),'only one pending payment can exist for each owner');
select ok(exists(select 1 from pg_indexes where schemaname='public' and indexname='billing_subscriptions_due_idx'),'subscription period index supports due-plan processing');
select ok(exists(select 1 from pg_indexes where schemaname='public' and indexname='billing_webhook_events_provider_event_id_key'),'provider event id is unique');
select ok(exists(select 1 from pg_indexes where schemaname='public' and indexname='billing_payments_external_reference_key'),'payment reference is unique');
select ok((select prosecdef from pg_proc where oid='public.apply_sandbox_payment_event(text,text,bigint,text,timestamp with time zone,jsonb,boolean)'::regprocedure),'webhook state transition is a security definer transaction');
select ok(has_function_privilege('service_role','public.apply_sandbox_payment_event(text,text,bigint,text,timestamp with time zone,jsonb,boolean)','EXECUTE'),'service role may apply verified payment events');
select ok(not has_function_privilege('anon','public.apply_sandbox_payment_event(text,text,bigint,text,timestamp with time zone,jsonb,boolean)','EXECUTE'),'anonymous users cannot apply payment events');
select ok(not has_function_privilege('authenticated','public.apply_sandbox_payment_event(text,text,bigint,text,timestamp with time zone,jsonb,boolean)','EXECUTE'),'signed-in users cannot apply payment events');
select * from extensions.finish();
rollback;
